    ('032640', DATE '2026-06-25', 177215016, 207969589),
    ('032640', DATE '2026-06-26', 177427782, 207969589)
),
normalized AS (
    SELECT history.*,
           CASE history.stock_code
               WHEN '003490' THEN 0.4999::numeric
               WHEN '015760' THEN 0.4000::numeric
               ELSE 0.4900::numeric
           END AS statutory_ratio
    FROM history
),
calculated AS (
    SELECT normalized.*,
           round(foreign_limit_quantity / statutory_ratio)::bigint AS total_listed_quantity
    FROM normalized
)
INSERT INTO foreign_ownership_snapshot (
    security_id, base_date, foreign_owned_quantity, total_listed_quantity,
    foreign_limit_quantity, available_quantity, ownership_rate,
    limit_exhaustion_rate, collected_at, source
)
SELECT security.id,
       calculated.base_date,
       calculated.foreign_owned_quantity,
       calculated.total_listed_quantity,
       calculated.foreign_limit_quantity,
       greatest(calculated.foreign_limit_quantity - calculated.foreign_owned_quantity, 0),
       round(calculated.foreign_owned_quantity * 100.0 / calculated.total_listed_quantity, 6),
       round(calculated.foreign_owned_quantity * 100.0 / calculated.foreign_limit_quantity, 6),
       CURRENT_TIMESTAMP,
       'KMARKET_CURATED_KRX_HISTORY_2019_2026'
FROM calculated
JOIN security ON security.stock_code = calculated.stock_code
ON CONFLICT (security_id, base_date) DO NOTHING;

-- 비거래 시간 재시작으로 다음 달력일에 잘못 적재된 KIS 스냅샷을 제거한다.
DELETE FROM foreign_ownership_snapshot snapshot
USING security
WHERE snapshot.security_id = security.id
  AND snapshot.source = 'KIS_REST_CURRENT_PRICE'
  AND snapshot.base_date > COALESCE(
      (
          SELECT max(price.trading_date)
          FROM market_daily_price price
          WHERE price.security_id = snapshot.security_id
      ),
      snapshot.base_date
  );

